  const headers = {
    "content-type": "application/json",
    accept: "application/json, text/event-stream",
    authorization: `Bearer ${TOKEN}`,
  };
  if (sid) headers["mcp-session-id"] = sid;
  const res = await fetch(URL_, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id: Date.now(), method, params }),
  });
  const got = res.headers.get("mcp-session-id");
  if (got) sid = got;
  const text = await res.text();
  if (!text.trim()) return { status: res.status, empty: true };
  const line = text.split("\n").find((l) => l.startsWith("data: "));
  const raw = line ? line.slice(6) : text;
  try { return JSON.parse(raw); } catch { return { status: res.status, raw: text.slice(0, 400) }; }
}
async function call(name, args) {
  const r = await rpc("tools/call", { name, arguments: args });
  const c = r?.result?.content?.[0]?.text ?? JSON.stringify(r).slice(0, 500);
  return c;
}
(async () => {
