/**
 * Structural matrix check. Rules:
 *  - EXACTLY ONE executor. Setting both `agent_id` and `device_worker_id` is
 *    rejected outright — see below.
 *  - Automated Behaviors (any event/schedule trigger) MUST have an executor.
 *    Triggers carry no executor of their own, and the scheduler/event SELECTs
 *    gate on the row-level columns — an executor-less automated Behavior
 *    would validate but never fire.
 *  - Manual-only Behaviors (no triggers) pass with or without an executor.
 */
export function assertBehaviorExecutorsResolve(
  triggers: BehaviorTriggerInput[] | null | undefined,
  defaults: BehaviorExecutorDefaults
): void {
  // "Exactly one executor" was the stated model but was never enforced: only
  // the ZERO case was rejected, so a write could set both and
  // `resolveBehaviorExecutor` would silently discard the agent (device-first).
  // That is how buremba b5/b71 died after #2499 rolled out — they kept their
  // agent_id, gained a device pin, and every run then hard-failed with
  // `no local agent executor configured for agent_kind=…`.
  //
  // Checked BEFORE the manual-only early return: a dual manual Behavior is
  // just as ambiguous, it simply has not been dispatched yet.
  if (defaults.agentId && defaults.deviceWorkerId) {
    throw new ToolUserError(
      "A Behavior has exactly one executor: set agent_id (managed agent) OR device_worker_id (device), not both. Setting both silently runs it on the device and ignores the agent — clear one to continue."
    );
  }
  const automated = (triggers ?? []).some(
    (trigger) => trigger.kind === "event" || trigger.kind === "schedule"
  );
  if (!automated) return;
  if (!resolveBehaviorExecutor(defaults)) {
    throw new ToolUserError(
      "Automated Behaviors need an executor: set agent_id (managed agent) or device_worker_id (device). Manual-only Behaviors (no triggers) may omit both."
    );
  }
}

